<template>
  <div>
    <router-link to="/" class="d-inline-block mb-3 small">&laquo; Back to Dashboard</router-link>
    <div class="d-flex justify-content-between align-items-end mb-4"><div><p class="eyebrow mb-1">Coordinator workspace</p><h1 class="h3">Affected venue bookings</h1><p class="text-muted mb-0">Original bookings remain preserved while you arrange replacement venues.</p></div><button class="btn btn-outline-primary" @click="load">Refresh</button></div>
    <div v-if="error" class="alert alert-danger">{{ error }}</div>
    <div v-else-if="!bookings.length" class="empty-state text-center">No affected bookings require replacement.</div>
    <article v-for="booking in bookings" :key="booking.id" class="card mb-3"><div class="card-body"><div class="d-flex justify-content-between gap-3"><div><h2 class="h5 mb-1">{{ booking.event_title }}</h2><p class="small text-muted mb-2">Affected booking <strong>#{{ shortId(booking.id) }}</strong></p><div class="alert alert-warning py-2 small mb-3"><strong>This booking is affected by venue unavailability.</strong> The original booking is preserved for reference while a replacement is arranged.</div><dl class="row small mb-2"><dt class="col-sm-4">Original venue</dt><dd class="col-sm-8">{{ booking.venue_name }}</dd><dt class="col-sm-4">Booked date/time</dt><dd class="col-sm-8">{{ formatDate(booking.start_time) }} to {{ formatDate(booking.end_time) }}</dd><dt class="col-sm-4">Original booking status</dt><dd class="col-sm-8">{{ booking.status }} <span class="text-muted">(preserved)</span></dd><dt class="col-sm-4">Unavailable period</dt><dd class="col-sm-8 text-danger">{{ formatDate(booking.unavailable_start) }} to {{ formatDate(booking.unavailable_end) }}</dd><dt class="col-sm-4">Reason</dt><dd class="col-sm-8 mb-0">{{ booking.unavailable_reason }}</dd></dl></div><span v-if="!booking.replacement_status" class="badge bg-warning text-dark align-self-start">Replacement required</span><span v-else-if="booking.replacement_status === 'pending'" class="badge bg-info text-dark align-self-start">Replacement request submitted</span><span v-else class="badge bg-secondary align-self-start">Replacement {{ booking.replacement_status }}</span></div><div v-if="booking.replacement_status" class="alert alert-info py-2 mt-3 mb-0"><strong>Replacement request submitted.</strong> {{ booking.replacement_venue_name }} for {{ formatDate(booking.replacement_start_time) }} to {{ formatDate(booking.replacement_end_time) }}<span v-if="booking.replacement_status === 'pending'"> <router-link class="alert-link" :to="{ name: 'batch-booking-request', query: { eventId: booking.event_id, editBookingId: booking.replacement_booking_id } }">Edit submitted request</router-link></span></div><router-link v-else class="btn btn-sm btn-accent mt-3" :to="{ name: 'batch-booking-request', query: { eventId: booking.event_id, replacementForBookingId: booking.id } }">Request replacement venue</router-link></div></article>
  </div>
</template>
<script>
import { authHeaders, clearSession } from '../services/auth'
export default { name: 'AffectedBookingsView', data() { return { bookings: [], error: '' } }, methods: { shortId(value) { return value ? value.slice(0, 8) : 'unknown' }, formatDate(value) { return value ? new Date(value).toLocaleString() : 'Not specified' }, async load() { this.error = ''; const response = await fetch('/api/bookings/affected', { headers: authHeaders() }); if (response.status === 401) { clearSession(); this.$router.push('/login'); return } const data = await response.json(); if (!response.ok) { this.error = data.error || 'Unable to load affected bookings'; return } this.bookings = this.$route.query.eventId ? data.filter(booking => booking.event_id === this.$route.query.eventId) : data } }, mounted() { this.load() } }
</script>
<style scoped>.empty-state { border: 1px dashed #cbd5e1; border-radius: .75rem; padding: 3rem 1rem; color: #52606d }</style>
